16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Period;
23	import java.util.Map;
24	
25	/**
26	 * Pure derivations of an {@link Owner}'s read-only attributes.
27	 *
28	 * <p>Each method computes one derived value from an owner's own field values and
29	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
30	 * exposes these through thin {@code @Transient} getters that pass in the relevant
31	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
32	 * to describe its persistent state and relationships while its growing family of
33	 * derived attributes lives together in one place.
34	 */
35	final class OwnerDerivations {
36	
37	    /** Fixed city-to-region table used to derive {@link #region}. */
38	    private static final Map<String, String> CITY_REGION = Map.of(
39	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
40	
41	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
42	     *  {@link #region} in preference to the city. */
43	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
44	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
45	
46	    private OwnerDerivations() {
47	    }
48	
49	    /**
50	     * The owner's locality, i.e. the canonical region it belongs to. This is read
51	     * from the region-and-hash {@code customerCode} identity: the region is the
52	     * {@code <REGION>} component that precedes the first {@code '-'} of the assigned
53	     * customer code (e.g. {@code NSW} for {@code NSW-9F86D081}). Until an owner has
54	     * been assigned a customer code (for example while its create request is still
55	     * being validated) this falls back to the region derived directly from its own
56	     * fields (see {@link #region(String, String)}).
57	     *
58	     * @return the canonical region string, or {@code "UNKNOWN"}
59	     */
60	    static String locality(String customerCode, String postcode, String city) {
61	        if (customerCode != null) {
62	            int dash = customerCode.indexOf('-');
63	            if (dash >= 0) {
64	                return customerCode.substring(0, dash);
65	            }
66	        }
67	        return region(postcode, city);
68	    }
69	
70	    /**
71	     * The canonical region derived for an owner from its own fields. The postcode is
72	     * consulted first: when it is present and falls within a known region's inclusive
73	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
74	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
75	     * known range does this fall back to the fixed city-to-region table
76	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
77	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
78	     * the same region for the known cities while disambiguating cities that share a name
79	     * via their postcode.
80	     *
81	     * @return the canonical region string, or {@code "UNKNOWN"}
82	     */
83	    static String region(String postcode, String city) {
84	        String byPostcode = regionForPostcode(postcode);
85	        if (byPostcode != null) {
86	            return byPostcode;
87	        }
88	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
89	    }
90	
91	    /**
92	     * The region whose inclusive postcode range contains the given postcode, or
93	     * {@code null} when the postcode is absent, not a four-digit number, or in no
94	     * known range.
95	     */
96	    private static String regionForPostcode(String postcode) {
97	        if (postcode == null || !postcode.matches("\\d{4}")) {
98	            return null;
99	        }
100	        int value = Integer.parseInt(postcode);
101	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
102	            int[] range = entry.getValue();
103	            if (value >= range[0] && value <= range[1]) {
104	                return entry.getKey();
105	            }
106	        }
107	        return null;
108	    }
109	
110	    /**
111	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
112	     * absent postcode is always accepted, a present postcode must be exactly four
113	     * digits and, when the region has a known inclusive postcode range
114	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
115	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
116	     * four-digit postcode.
117	     *
118	     * @return {@code true} if the postcode is absent or valid for the region
119	     */
120	    static boolean postcodeMatchesRegion(String postcode, String region) {
121	        if (postcode == null) {
122	            return true;
123	        }
124	        if (!postcode.matches("\\d{4}")) {
125	            return false;
126	        }
127	        int[] range = REGION_POSTCODES.get(region);
128	        if (range == null) {
129	            return true;
130	        }
131	        int value = Integer.parseInt(postcode);
132	        return value >= range[0] && value <= range[1];
133	    }
134	
135	    /**
136	     * The owner's membership level, a number from 1 to 3 assigned at creation:
137	     * starting at 1, add 1 when an {@code email} is present and add 1 when
138	     * {@code namesakeCount} is 0, capped at 3 (level 4 is reserved for tenure).
139	     *
140	     * @return the membership level, from 1 to 3
141	     */
142	    static int membershipLevel(String email, Integer namesakeCount) {
143	        int level = 1;
144	        if (hasEmail(email)) {
145	            level++;
146	        }
147	        if (namesakeCount != null && namesakeCount == 0) {
148	            level++;
149	        }
150	        return Math.min(level, 3);
151	    }
152	
153	    /**
154	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
155	     * is present, otherwise {@code "PHONE"}.
156	     *
157	     * @return {@code "EMAIL"} or {@code "PHONE"}
158	     */
159	    static String contactPreference(String email) {
160	        if (hasEmail(email)) {
161	            return "EMAIL";
162	        }
163	        return "PHONE";
164	    }
165	
166	    /**
167	     * Whether the owner has an email address on file, i.e. its {@code email} is present
168	     * and not blank. This is the single presence test the email-driven derivations share
169	     * (a membership-level factor and the {@link #contactPreference(String) contact
170	     * preference}), so they agree on exactly what counts as "has an email".
171	     */
172	    private static boolean hasEmail(String email) {
173	        return email != null && !email.isBlank();
174	    }
175	
176	    /**
177	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
178	     * given {@code customerCode}, processed right-to-left with every second digit
179	     * doubled (and reduced by 9 when the double exceeds 9). Non-digit characters are
180	     * ignored, and an absent or digit-free customer code yields {@code 0}.
181	     *
182	     * @return the Luhn check digit, from 0 to 9
183	     */
184	    static int checkDigit(String customerCode) {
185	        int sum = 0;
186	        boolean doubleDigit = true;
187	        for (int i = (customerCode == null ? 0 : customerCode.length()) - 1; i >= 0; i--) {
188	            char c = customerCode.charAt(i);
189	            if (c < '0' || c > '9') {
190	                continue;
191	            }
192	            int d = c - '0';
193	            if (doubleDigit) {
194	                d *= 2;
195	                if (d > 9) {
196	                    d -= 9;
197	                }
198	            }
199	            sum += d;
200	            doubleDigit = !doubleDigit;
201	        }
202	        return (10 - (sum % 10)) % 10;
203	    }
204	
205	    /**
206	     * The owner's age band, derived from its {@code birthDate} measured against its
207	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
208	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
209	     * over. The age is the number of whole years between the two dates. Returns
210	     * {@code null} when either date is absent, so no band is reported for an owner
211	     * without a supplied birth date.
212	     *
213	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
214	     */
215	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
216	        if (birthDate == null || registrationDate == null) {
217	            return null;
218	        }
219	        int age = Period.between(birthDate, registrationDate).getYears();
220	        if (age < 18) {
221	            return "MINOR";
222	        }
223	        if (age < 65) {
224	            return "ADULT";
225	        }
226	        return "SENIOR";
227	    }
228	
229	    /**
230	     * The single derived key used for duplicate detection, formed as
231	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
232	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
233	     * is the stored (lower-cased) email or the empty string when absent, and the
234	     * household component is the stored {@code householdId} or the empty string
235	     * when the owner belongs to no household.
236	     *
237	     * @return the owner's identity key
238	     */
239	    static String identityKey(String telephone, String email, String householdId) {
240	        String tel = telephone == null ? "" : telephone;
241	        String mail = email == null ? "" : email;
242	        String household = householdId == null ? "" : householdId;
243	        return tel + "|" + mail + "|" + household;
244	    }
245	
246	    /**
247	     * The owner's customer code, formatted {@code <REGION>-<HASH8>}: {@code region} is
248	     * the owner's canonical region (see {@link #region(String, String)}) and HASH8 is the
249	     * first eight upper-case hexadecimal characters of the SHA-256 digest of the owner's
250	     * normalised telephone concatenated with its last name (e.g. {@code NSW-9F86D081}).
251	     *
252	     * @return the customer code
253	     */
254	    static String customerCode(String region, String telephone, String lastName) {
255	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
256	        return String.format("%s-%s", region, hash8);
257	    }
258	
259	    /**
260	     * The stable identifier for the household an owner belongs to, derived
261	     * deterministically from its {@code normalizedLastName} and {@code postcode} so that
262	     * every owner sharing a last name and postcode resolves to the same value. It is the
263	     * first twelve lower-case hexadecimal characters of the SHA-256 digest of
264	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes the
265	     * empty string).
266	     *
267	     * @return the household identifier
268	     */
269	    static String householdId(String normalizedLastName, String postcode) {
270	        String pc = postcode == null ? "" : postcode;
271	        return sha256Hex(normalizedLastName + "|" + pc).substring(0, 12);
272	    }
273	
274	    /**
275	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
276	     * hexadecimal string. Callers take the prefix and case they need.
277	     */
278	    static String sha256Hex(String value) {
279	        try {
280	            byte[] digest = MessageDigest.getInstance("SHA-256")
281	                .digest(value.getBytes(StandardCharsets.UTF_8));
282	            StringBuilder hex = new StringBuilder(digest.length * 2);
283	            for (byte b : digest) {
284	                hex.append(String.format("%02x", b));
285	            }
286	            return hex.toString();
287	        } catch (NoSuchAlgorithmException e) {
288	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
289	        }
290	    }
291	}
